#!/bin/sh
# Runtime checks of all accepted M (measurement 3) and P (this measurement) variants.
# Usage: run-all.sh <schild> <validator workdir root (contains M/ and P/)>
B=$1; V=$2; R=$(cd "$(dirname "$0")" && pwd)/run-bypass.sh
A='?q=%3Cscript%3Ealert(1)%3C/script%3E&id=1%27%20OR%201=1--'
X="a.example.test|/$A"
F="-H 'Content-Type: application/x-www-form-urlencoded' --data-binary @/tmp/abend/postxss.txt"
W=$V/M
$R $B $W M01-N01-fixed-schild-in-handle-errors "$X" "b.example.test|/$A" "b.example.test|/plain" "b.example.test|/$A|-H 'Schild-Passed: 1' -H 'X-Schild-Passed: true'" "b.example.test|/$A&schild.passed=1"
$R $B $W M02-N03-fixed-static-site-404 "b.example.test|/missing$A" "b.example.test|/missing"
$R $B $W M03-N23-fixed-basic-auth-401 "b.example.test|/$A" "b.example.test|/"
$R $B $W M04-forge-marker-vars "b.example.test|/$A" "b.example.test|/plain"
$R $B $W M05-forge-marker-map "b.example.test|/$A" "b.example.test|/plain"
$R $B $W M06-forge-marker-vars-in-handle-errors "b.example.test|/$A" "b.example.test|/plain"
$R $B $W M10-handle-errors-invoke-guarded-named "$X" "b.example.test|/$A" "b.example.test|/plain"
$R $B $W M12-unprotected-site-handle-errors-proxy "a.example.test|/x$A" "a.example.test|/x" "b.example.test|/$A"
$R $B $W M13-unprotected-wildcard-handle-errors-catches-guarded "a.example.test|/adm$A" "a.example.test|/adm" "c.example.test|/$A"
$R $B $W M15-schild-only-in-handle-errors-error-site "b.example.test|/$A" "b.example.test|/plain" "c.example.test|/missing$A" "c.example.test|/missing"
$R $B $W M16-request-body-limit-error-guarded-errors "a.example.test|/$A|-d @/tmp/m3big.txt" "a.example.test|/up|-d @/tmp/m3big.txt" "a.example.test|/up?x=1|-d @/tmp/m3bigxss.txt" "a.example.test|/small|-d a=1"
$R $B $W M17-backend-error-twice-schild "a.example.test|/__status/500" "a.example.test|/__status/500$A" "a.example.test|/ok"
$R $B $W M18-route-strip-query-before-schild-restore-in-errors "a.example.test|/$A" "a.example.test|/plain?x=1"
$R $B $W M19-errors-site-snippet-empty-rollback "b.example.test|/missing$A" "b.example.test|/missing"
$R $B $W M20-handle-errors-only-respond-other-proxy-site "b.example.test|/missing$A"
$R $B $W M23-intercept-error-guarded "a.example.test|/boom$A" "a.example.test|/boom"
$R $B $W M24-route-rewrite-drop-query-before-schild-error "a.example.test|/app/$A" "a.example.test|/app/?x=1" "a.example.test|/app/|-X POST $F"
$R $B $W M25-route-rewrite-path-only-file-server-404 "a.example.test|/missing$A" "a.example.test|/missing?x=1" "a.example.test|/missing|-X POST $F"
$R $B $W M26-route-request-header-removed-before-schild "a.example.test|/|-H 'X-Payload: <script>alert(1)</script>'" "a.example.test|/plain"
W=$V/P
$R $B $W P01-errors-rewrite-to-inspected-uri-then-restore "a.example.test|/app/$A" "a.example.test|/app/?x=1"
$R $B $W P04-method-rewrite-before-schild-error "a.example.test|/app/|-X POST $F" "a.example.test|/app/$A|-X POST -d a=1" "a.example.test|/app/|-X POST -d a=1" "a.example.test|/app/|-X DELETE"
$R $B $W P05-method-override-headers "a.example.test|/u/1|-X POST -H 'X-HTTP-Method-Override: PUT' $F" "a.example.test|/u/1$A|-X POST -H 'X-HTTP-Method-Override: DELETE' -d a=1" "a.example.test|/u/1|-X POST -H 'X-HTTP-Method-Override: PUT' -d _method=PUT" "a.example.test|/u/1|-X PUT $F"
$R $B $W P06-host-rewrite-before-schild-error "a.example.test|/$A" "a.example.test|/plain" "a.example.test|/plain|-H 'X-Forwarded-Host: <script>alert(1)</script>'"
$R $B $W P07-other-site-hides-query-errors-in-guarded-site "a.example.test|/app/$A" "a.example.test|/app/?x=1" "b.example.test|/$A"
$R $B $W P08-handle-path-error-guarded-errors "a.example.test|/app/x$A" "a.example.test|/app/x?y=1" "a.example.test|/other?y=1"
$R $B $W P09-uri-query-delete-before-schild-error "a.example.test|/$A" "a.example.test|/?q=fine&z=1"
$R $B $W P10-request-body-set-before-schild-error "a.example.test|/|-X POST $F" "a.example.test|/|-X POST -d a=1"
$R $B $W P11-file-server-404-same-uri-once "a.example.test|/missing$A" "a.example.test|/missing?x=1" "a.example.test|/missing|-X POST $F" "a.example.test|/missing|-X POST -d a=1"
$R $B $W P12-errors-rewrite-restore-in-other-site "a.example.test|/app/$A" "a.example.test|/app/?x=1"
$R $B $W P13-errors-schild-then-rewrite-orig "a.example.test|/app/$A" "a.example.test|/app/?x=1"
$R $B $W P15-errors-vars-rewrite-to-inspected-then-restore "a.example.test|/app/$A"
$R $B $W P17-site-vars-save-hide-restore-nested "a.example.test|/app/$A"
$R $B $W P18-errors-vars-rewrite-to-inspected-then-restore-nested "a.example.test|/app/$A"
$R $B $W P19-errors-orig-uri-restore-nested "a.example.test|/app/$A"
$R $B $W P20-site-uri-replace-after-schild "a.example.test|/app/$A" "a.example.test|/app/?x=1"
$R $B $W P21-errors-rewrite-to-inspected-then-uri-replace "a.example.test|/app/$A" "a.example.test|/app/?x=1"
$R $B $W P22-errors-schild-first-then-uri-replace "a.example.test|/app/$A" "a.example.test|/app/?x=1"
